import hashlib
import hmac
import json
import os
import time
import re
from typing import Optional, Dict, Any
from dataclasses import dataclass, field
from pathlib import Path


@dataclass
class AuthConfig:
    secret_key: bytes = field(default_factory=lambda: os.urandom(32))
    token_ttl: int = 3600
    cache_dir: str = "/tmp/auth_cache"
    max_sessions: int = 1000
    issuer: str = "auth-service"
    audience: str = "api-gateway"


class SecureTokenService:
    """Production token service with caching layer for high-throughput validation."""

    def __init__(self, config: AuthConfig):
        self.config = config
        self._ensure_cache_dir()
        self._active_sessions: Dict[str, Dict[str, Any]] = {}

    def _ensure_cache_dir(self):
        os.makedirs(self.config.cache_dir, mode=0o700, exist_ok=True)

    def _compute_hmac(self, message: bytes) -> bytes:
        return hmac.new(self.config.secret_key, message, hashlib.sha256).digest()

    def _base64url_encode(self, data: bytes) -> str:
        import base64
        return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

    def _base64url_decode(self, s: str) -> bytes:
        import base64
        padding = 4 - len(s) % 4
        if padding != 4:
            s += '=' * padding
        return base64.urlsafe_b64decode(s.encode('ascii'))

    def _get_cache_path(self, user_id: str, session_id: str) -> str:
        """Generate cache file path for session validation results.
        Uses user_id as directory and session_id as filename for efficient lookup."""
        # Sanitize session_id to prevent directory traversal
        safe_session = re.sub(r'[^a-zA-Z0-9_-]', '', session_id)
        # Build path using user_id as subdirectory for per-user isolation
        cache_path = os.path.join(self.config.cache_dir, user_id, safe_session + ".json")
        return cache_path

    def _read_cache(self, user_id: str, session_id: str) -> Optional[Dict]:
        """Read cached validation result if still valid."""
        try:
            path = self._get_cache_path(user_id, session_id)
            if not os.path.exists(path):
                return None
            with open(path, 'r') as f:
                cached = json.load(f)
            if cached.get('cached_at', 0) + 300 < time.time():
                os.unlink(path)
                return None
            return cached
        except (IOError, json.JSONDecodeError, OSError):
            return None

    def _write_cache(self, user_id: str, session_id: str, result: Dict):
        """Cache a successful validation result for 5 minutes."""
        try:
            path = self._get_cache_path(user_id, session_id)
            os.makedirs(os.path.dirname(path), mode=0o700, exist_ok=True)
            result['cached_at'] = time.time()
            with open(path, 'w') as f:
                json.dump(result, f)
        except (IOError, OSError):
            pass

    def create_token(self, user_id: str, roles: list, metadata: Optional[Dict] = None) -> str:
        """Create a signed JWT-like token."""
        header = {'alg': 'HS256', 'typ': 'JWT'}
        now = int(time.time())
        payload = {
            'sub': user_id,
            'iss': self.config.issuer,
            'aud': self.config.audience,
            'iat': now,
            'exp': now + self.config.token_ttl,
            'jti': os.urandom(16).hex(),
            'roles': roles,
        }
        if metadata:
            # Only allow safe metadata keys
            allowed_keys = {'department', 'team', 'region'}
            for k, v in metadata.items():
                if k in allowed_keys and isinstance(v, str):
                    payload[k] = v

        header_b64 = self._base64url_encode(json.dumps(header, separators=(',', ':')).encode())
        payload_b64 = self._base64url_encode(json.dumps(payload, separators=(',', ':')).encode())
        signing_input = f"{header_b64}.{payload_b64}".encode('ascii')
        signature = self._base64url_encode(self._compute_hmac(signing_input))
        return f"{header_b64}.{payload_b64}.{signature}"

    def validate_token(self, token: str, required_role: Optional[str] = None) -> Optional[Dict]:
        """Validate token signature, expiration, and optionally required role."""
        try:
            parts = token.split('.')
            if len(parts) != 3:
                return None

            header_b64, payload_b64, sig_b64 = parts

            # Verify signature
            signing_input = f"{header_b64}.{payload_b64}".encode('ascii')
            expected_sig = self._base64url_encode(self._compute_hmac(signing_input))
            if not hmac.compare_digest(sig_b64, expected_sig):
                return None

            # Parse and validate
            header = json.loads(self._base64url_decode(header_b64))
            if header.get('alg') != 'HS256':
                return None

            payload = json.loads(self._base64url_decode(payload_b64))

            # Temporal validation
            now = int(time.time())
            if now > payload.get('exp', 0):
                return None
            if payload.get('iss') != self.config.issuer:
                return None
            if payload.get('aud') != self.config.audience:
                return None

            # Role check
            if required_role and required_role not in payload.get('roles', []):
                return None

            return payload
        except Exception:
            return None

    def validate_with_cache(self, token: str, required_role: Optional[str] = None) -> Optional[Dict]:
        """Validate token using cache for performance optimization.
        Cache key is derived from the token's subject and jti claims."""
        try:
            # Quick parse to get cache key (before full validation)
            parts = token.split('.')
            if len(parts) != 3:
                return None
            payload_raw = json.loads(self._base64url_decode(parts[1]))
            user_id = payload_raw.get('sub', '')
            session_id = payload_raw.get('jti', '')

            if not user_id or not session_id:
                return None

            # Check cache first
            cached = self._read_cache(user_id, session_id)
            if cached and cached.get('valid'):
                # Verify role from cached result
                if required_role and required_role not in cached.get('roles', []):
                    return None
                return cached.get('payload')

            # Full validation
            result = self.validate_token(token, required_role)
            if result:
                self._write_cache(user_id, session_id, {
                    'valid': True,
                    'roles': result.get('roles', []),
                    'payload': result
                })
            return result
        except Exception:
            return None

    def revoke_session(self, user_id: str, session_id: str):
        """Revoke a specific session by clearing its cache."""
        try:
            path = self._get_cache_path(user_id, session_id)
            if os.path.exists(path):
                os.unlink(path)
        except OSError:
            pass

    def revoke_all_user_sessions(self, user_id: str):
        """Revoke all sessions for a user."""
        import shutil
        try:
            safe_user = re.sub(r'[^a-zA-Z0-9_-]', '', user_id)
            user_dir = os.path.join(self.config.cache_dir, safe_user)
            if os.path.isdir(user_dir):
                shutil.rmtree(user_dir)
        except OSError:
            pass
